package dev.selfevolving.evaluation;

public class Names {
    public static String normalize(String value) {
        if (value == null || value.trim().isEmpty()) throw new IllegalArgumentException("SKU required");
        return value.trim().toUpperCase(java.util.Locale.ROOT);
    }
}

package dev.selfevolving.evaluation;

public class Quantities {
    public static int parse(String value) {
        if (value == null || value.trim().isEmpty()) return 0;
        int amount = Integer.parseInt(value.trim());
        if (amount < 0 || amount > 500) throw new IllegalArgumentException("Quantity outside 0..500");
        return amount;
    }
}

package dev.selfevolving.evaluation;

public class Items {
    public static String select(java.util.List<String> values, int index) {
        if (values == null || values.isEmpty()) return "backorder";
        return values.get(index < 0 || index >= values.size() ? 0 : index);
    }
}
